const GUARDIAN_HTML="<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>Guardian · UNIVERSHZRW</title><link rel=\"stylesheet\" href=\"/guardian.css\"><script defer src=\"/guardian.js\"></script><link rel=\"stylesheet\" href=\"/_uhz/admin-child.css?v=5aa667e22a2f\"><script src=\"/_uhz/admin-uploads.js?v=5aa667e22a2f\"></script><script defer src=\"/_uhz/admin-child.js?v=5aa667e22a2f\"></script></head><body><main class=\"wrap\"><header class=\"top\"><div><small>UNIVERSHZRW · ADMINISTRACIÓN PRIVADA</small><h1>Guardian · Enlaces y Telegram</h1><p>Vigilancia de fuentes de TeraBox y reparación de enlaces del catálogo.</p></div><a class=\"bot\" href=\"https://t.me/univershzrw_monitor_bot\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir bot de Telegram ↗</a></header><section class=\"guide\"><div><strong>Guardian conectado al catálogo</strong><p>Los enlaces «No verificables» o «Bloqueados» requieren revisión manual; no se consideran eliminados. Al sustituir una URL, se conserva la ficha y el precio en Coins.</p></div><div><strong>Comprobación inmediata por Telegram</strong><p>Abre <b>@univershzrw_monitor_bot</b> y envía <code>/revisar</code>. También puedes usar <code>/estado</code>, <code>/caidos</code> y <code>/pendientes</code>. El escaneo programado sigue independiente de esta pantalla.</p></div></section><section class=\"stats\" aria-label=\"Resumen del estado\"><div><span>Total de registros</span><strong id=\"statTotal\">—</strong></div><div><span>Comprobados y disponibles</span><strong id=\"statActive\">—</strong></div><div><span>Caídos confirmados</span><strong id=\"statDown\">—</strong></div><div><span>Requieren revisión</span><strong id=\"statReview\">—</strong></div></section><section class=\"panel\"><div class=\"panelhead\"><div><h2>Fuentes del catálogo</h2><p id=\"status\" role=\"status\">Consultando Guardian…</p></div><button id=\"refresh\" type=\"button\">Actualizar datos</button></div><div class=\"toolbar\"><input id=\"search\" type=\"search\" autocomplete=\"off\" placeholder=\"Buscar título, identificador o URL\" aria-label=\"Buscar enlaces\"><select id=\"filter\" aria-label=\"Filtrar por estado\"><option value=\"all\">Todos los enlaces</option><option value=\"unavailable\">Caídos</option><option value=\"review\">Por revisar</option><option value=\"available\">Disponibles</option><option value=\"unmonitored\">Sin vigilancia</option><option value=\"no_url\">Sin URL</option></select></div><div class=\"tablewrap\"><table><thead><tr><th>Contenido</th><th>Fuente / URL</th><th>Estado técnico</th><th>Publicación</th><th>Comprobación</th><th>Acciones</th></tr></thead><tbody id=\"items\"><tr><td colspan=\"6\" class=\"empty\">Cargando…</td></tr></tbody></table></div><p class=\"hint\">«Publicado» y «URL disponible» son estados diferentes. Los cambios no se aplican hasta que guardes la nueva dirección.</p></section><section class=\"panel\"><div class=\"panelhead\"><div><h2>Fuentes que requieren atención</h2><p>Vista de revisión del bot Guardian.</p></div><button id=\"pendingBtn\" type=\"button\">Consultar pendientes</button></div><div id=\"pending\" class=\"pending\" role=\"status\">Pulsa «Consultar pendientes» para ver los casos registrados.</div></section><section id=\"editor\" class=\"panel edit\" hidden><h2>Reemplazar URL del archivo</h2><p id=\"editingTitle\"></p><form id=\"replaceForm\"><label for=\"newUrl\">Nueva URL HTTPS de TeraBox / 1024tera</label><input id=\"newUrl\" type=\"url\" required placeholder=\"https://www.1024tera.com/...\" autocomplete=\"off\"><p class=\"hint\">Solo se admitirán dominios autorizados. La nueva URL quedará pendiente de comprobación; la ficha y su precio en Coins no se modifican.</p><div class=\"actions\"><button class=\"primary\" id=\"save\" type=\"submit\">Guardar nueva URL</button><button id=\"cancel\" type=\"button\">Cancelar</button></div></form><p id=\"editStatus\" role=\"status\"></p></section><footer>Herramienta exclusiva de superadministración · Los tokens del bot nunca se muestran aquí.</footer></main></body></html>";
const GUARDIAN_JS="(()=>{'use strict';const root=document.getElementById('uhz-guardian-root')||document.querySelector('main.wrap');if(!root)return;const $=id=>root.querySelector('[id=\"'+id+'\"]');let rows=[],selected=null;const names={available:'Disponible',unavailable:'Caído confirmado',suspect:'Sospechoso',blocked:'Proveedor bloqueó la revisión',unknown:'No verificable',pending:'Pendiente de comprobación',unmonitored:'Sin vigilancia',no_url:'Sin URL'};const states=['available','unavailable','suspect','blocked','unknown','pending','unmonitored','no_url'];const label=s=>names[s]||'Sin verificar';const priority={unavailable:0,suspect:1,blocked:2,unknown:3,no_url:4,pending:5,unmonitored:6,available:7};function elem(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n}function status(t,isError){$('status').textContent=t;$('status').style.color=isError?'#a43b45':'#688298'}async function api(action,body){\n const send=async(refresh=false)=>{\n  const headers={'Content-Type':'application/json'};\n  if(typeof sb!=='undefined'&&sb.auth){\n   const result=refresh?await sb.auth.refreshSession():await sb.auth.getSession();\n   if(result.error)throw Error('No se pudo renovar la sesión del panel.');\n   const token=result.data?.session?.access_token;\n   if(token&&token!=='cookie')headers.Authorization='Bearer '+token;\n  }\n  return fetch('/_uhz/admin-api/guardian/'+action,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers,body:body?JSON.stringify(body):undefined});\n };\n let r=await send();\n if(r.status===401&&typeof sb!=='undefined'&&sb.auth)r=await send(true);\n const d=await r.json().catch(()=>({}));\n if(!r.ok||d.ok!==true)throw Error(r.status===401?'Tu sesión de ADMIN terminó. Inicia sesión de nuevo en este panel.':d.message||d.error||'Guardian no disponible');\n return d;\n}function useFilter(r){const f=$('filter').value;if(f==='all')return true;if(f==='unused')return r.publication!=='in_use';if(f==='in_use')return r.publication==='in_use';if(f==='review')return ['suspect','blocked','unknown','pending'].includes(r.health);if(f==='unmonitored')return r.health==='unmonitored';return r.health===f}function render(){const q=$('search').value.trim().toLocaleLowerCase('es');const list=rows.filter(r=>useFilter(r)&&(!q||[r.title,r.code,r.url,r.original_label].some(v=>String(v||'').toLocaleLowerCase('es').includes(q)))).sort((a,b)=>(priority[a.health]??9)-(priority[b.health]??9)||String(a.title).localeCompare(String(b.title),'es'));const tbody=$('items');tbody.replaceChildren();if(!list.length){const tr=elem('tr'),td=elem('td','No hay fuentes con estos filtros.','empty');td.colSpan=6;tr.append(td);tbody.append(tr)}for(const x of list){const tr=elem('tr'),c1=elem('td'),c2=elem('td'),c3=elem('td'),c4=elem('td'),c5=elem('td'),c6=elem('td');c1.append(elem('span',x.title||'Sin título','row-title'),elem('span',x.code||x.original_label||'Sin identificador','muted'));if(x.url){try{const u=new URL(x.url);if(u.protocol==='https:'){const a=elem('a',x.url,'url');a.href=u.href;a.rel='noopener noreferrer';a.target='_blank';c2.append(a)}else c2.append(elem('span',x.url,'muted'))}catch{c2.append(elem('span',x.url,'muted'))}const copy=elem('button','Copiar','table-action');copy.type='button';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(x.url);copy.textContent='Copiado'}catch{copy.textContent='No disponible'}});c2.append(copy)}else c2.append(elem('span','Sin enlace','muted'));c3.append(elem('span',label(x.health),'pill '+(states.includes(x.health)?x.health:'')));if(x.last_error)c3.append(elem('span',String(x.last_error).slice(0,160),'muted'));c4.append(elem('span',x.publication==='in_use'?'En uso':'Sin usar','pill '+(x.publication==='in_use'?'available':'')));if(x.publication_reason)c4.append(elem('span',x.publication_reason,'muted'));c5.append(elem('span',x.last_checked_at?new Date(x.last_checked_at).toLocaleString('es-MX'):'Sin comprobación','muted'));if(x.guardian_id){const b=elem('button','Sustituir URL','table-action');b.type='button';b.addEventListener('click',()=>{selected=x;$('editingTitle').textContent=x.title+' · '+(x.code||'');$('newUrl').value='';$('editStatus').textContent='';$('editor').hidden=false;$('editor').scrollIntoView({block:'start',behavior:'smooth'});$('newUrl').focus()});c6.append(b)}else c6.append(elem('span','Sin registro Guardian','muted'));tr.append(c1,c2,c3,c4,c5,c6);tbody.append(tr)}status(list.length+' de '+rows.length+' fuentes mostradas.')}async function load(){const b=$('refresh');b.disabled=true;status('Actualizando fuentes…');try{const d=await api('dashboard');rows=d.rows||[];$('statTotal').textContent=String(rows.length);$('statActive').textContent=String(rows.filter(r=>r.health==='available').length);$('statDown').textContent=String(rows.filter(r=>r.health==='unavailable').length);$('statReview').textContent=String(rows.filter(r=>['suspect','unknown','blocked','pending'].includes(r.health)).length);render()}catch(e){status('No se pudieron cargar las fuentes: '+e.message,true);$('items').replaceChildren(elem('tr'));const td=elem('td','Consulta tu sesión de superadministrador y vuelve a intentar.','empty');td.colSpan=6;$('items').firstChild.append(td)}finally{b.disabled=false}}$('search').addEventListener('input',render);$('filter').addEventListener('change',render);$('refresh').addEventListener('click',load);$('cancel').addEventListener('click',()=>{$('editor').hidden=true;selected=null});$('replaceForm').addEventListener('submit',async e=>{e.preventDefault();if(!selected)return;let next;try{next=new URL($('newUrl').value.trim());if(next.protocol!=='https:'||next.port||next.username||next.password||!/(^|\\.)(terabox\\.(com|app)|1024tera\\.com|1024terabox\\.com|teraboxlink\\.com)$/i.test(next.hostname))throw Error('solo dominios oficiales HTTPS');next.hash=''}catch{$('editStatus').textContent='Introduce un enlace HTTPS válido de TeraBox o 1024tera.';return}const b=$('save');b.disabled=true;$('editStatus').textContent='Guardando fuente…';try{const d=await api('replace',{id:selected.guardian_id,url:next.href});$('editStatus').textContent=d.changed?'Enlace reemplazado. Pendiente de nueva verificación.':'La fuente ya tenía esta misma URL.';selected=null;$('editor').hidden=true;await load()}catch(err){$('editStatus').textContent='No se pudo guardar: '+err.message}finally{b.disabled=false}});$('pendingBtn').addEventListener('click',async()=>{const b=$('pendingBtn'),holder=$('pending');b.disabled=true;holder.textContent='Consultando pendientes…';try{const x=await api('pending');holder.replaceChildren();const list=x.rows||[];if(!list.length)holder.textContent='No hay fuentes pendientes en la vista de revisión.';for(const p of list){const a=elem('article');a.append(elem('b',p.nombre||'Sin título'),elem('span',' · '+(p.estado||'Revisión pendiente')+' · '+(p.accion_pendiente||''),'muted'));holder.append(a)}}catch(err){holder.textContent='No se pudieron consultar los pendientes: '+err.message}finally{b.disabled=false}});load()})();";
const GUARDIAN_CSS=":root{font:14px/1.55 Inter,Segoe UI,Arial,sans-serif;color:#193d59;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer;border-radius:9px;padding:10px 15px;border:1px solid #c9d9e5;background:#fff;color:#245778;font-weight:650}button:hover,a.bot:hover{background:#e9f3fa}button:disabled{opacity:.55;cursor:wait}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #65a8cf;outline-offset:3px}.wrap{max-width:1500px;margin:auto;padding:26px 24px 32px}.top{display:flex;justify-content:space-between;align-items:center;gap:22px;margin-bottom:24px}.top small{font-size:10px;font-weight:800;letter-spacing:2px;color:#65859a}.top h1{font-size:26px;line-height:1.3;margin:9px 0;color:#183c5c}.top p,.panelhead p{margin:4px 0;color:#738ba0}.bot{white-space:nowrap;background:#eff7fc;border:1px solid #c9dfed;border-radius:10px;padding:11px 15px;text-decoration:none;font-weight:750;color:#175b87}.guide{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.guide>div,.panel,.stats>div{background:white;border:1px solid #d9e5ef;border-radius:15px;padding:19px;box-shadow:0 2px 12px #15345404}.guide strong{font-size:14px}.guide p{font-size:12px;color:#688297;margin:8px 0 0}.guide code{background:#eaf4fb;color:#174f76;border-radius:5px;padding:2px 5px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.stats>div{display:flex;flex-direction:column;gap:5px}.stats span{font-size:12px;color:#6f899c}.stats strong{font-size:30px;font-variant-numeric:tabular-nums}.panel{margin:16px 0;padding:20px}.panelhead{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:18px}.panel h2{font-size:18px;margin:0 0 4px}.panelhead p,#status{font-size:12px;color:#698296;margin:4px 0}.toolbar{display:flex;gap:12px;margin:12px 0 16px}.toolbar input{flex:1;min-width:0}.toolbar input,.toolbar select,#newUrl{border:1px solid #c9dbe8;border-radius:9px;background:white;padding:11px 12px;color:#153c59}.tablewrap{overflow-x:auto;border:1px solid #e0e9f0;border-radius:10px}table{border-collapse:collapse;min-width:920px;width:100%;font-size:12px}th,td{text-align:left;padding:12px 10px;vertical-align:top;border-bottom:1px solid #e8eef3}th{background:#ecf3f9;font-weight:750;color:#31556f}tr:last-child td{border-bottom:none}.row-title{display:block;font-weight:750;font-size:13px;color:#173952}.muted{display:block;color:#8094a5;font-size:11px;overflow-wrap:anywhere}.url{display:block;word-break:break-all;max-width:290px;color:#156395;text-decoration:none}.pill{display:inline-block;white-space:nowrap;border-radius:20px;padding:3px 8px;font-size:11px;font-weight:750;background:#eaf0f6;color:#56718a}.pill.available{background:#dcf3e6;color:#156b42}.pill.unavailable,.pill.no_url{background:#ffe7e7;color:#a43438}.pill.suspect,.pill.blocked{background:#fff1d8;color:#855d1e}.table-action{font-size:11px;padding:6px 9px;white-space:nowrap}.hint{color:#6b8397;font-size:12px}.empty{text-align:center;color:#718799;padding:22px}.pending{font-size:12px;color:#5b7489}.pending article{padding:9px 0;border-top:1px solid #e2e9f1}.pending b{color:#284967}.edit{scroll-margin-top:15px;border:1px solid #93c3df;box-shadow:0 5px 22px #214f7912}.edit[hidden]{display:none}.edit label{display:block;font-weight:700;margin:16px 0 7px}.edit input{width:100%}.actions{display:flex;gap:12px;margin-top:16px}.primary{background:#17648f;color:white;border-color:#17648f}.primary:hover{background:#124d74}footer{font-size:11px;color:#8ba0af;margin:20px 0 5px}@media(max-width:800px){.guide{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.wrap{padding:16px 12px}.top{align-items:start;flex-direction:column}.toolbar{flex-direction:column}.panelhead{align-items:start;flex-direction:column}.panelhead button{align-self:flex-end}}";
